import{AsyncHopRounds,canonical,need}from'./core.js';
import{Machine}from'./machine.js';
export class PeerSession{
 constructor(machine,gpu,onCommit,onStatus){this.machine=machine;this.gpu=gpu;this.onCommit=onCommit;this.onStatus=onStatus;this.local();}
 local(){this.close();this.member='A';this.initial=this.machine.checkpoint();this.log=[];this.commits=new Map;this.receipts=new Map;this.ready=true;this.rounds=new AsyncHopRounds(['A'],async(batch,r)=>this.commit(batch,r));}
 close(){this.pc?.close();this.pc=null;this.channel=null;this.ready=false;}
 reset(checkpoint,member){this.close();this.machine=new Machine(checkpoint);this.initial=this.machine.checkpoint();this.member=member;this.log=[];this.commits=new Map;this.receipts=new Map;this.rounds=new AsyncHopRounds(['A','B'],async(batch,r)=>this.commit(batch,r));}
 async commit(batch,r){const result=await this.machine.apply(batch,this.gpu);this.log.push(...batch);this.commits.set(r,result.checkpoint);this.send({type:'commit',round:r,checkpoint:result.checkpoint});this.checkReceipts();this.onCommit(result,r);return result;}
 send(p){if(this.channel?.readyState==='open')this.channel.send(JSON.stringify(p));}
 checkReceipts(){for(const[r,c]of this.receipts)if(this.commits.has(r)){need(canonical(c)===canonical(this.commits.get(r)),'Peer checkpoint mismatch');this.receipts.delete(r);}}
 attach(c){this.channel=c;c.onopen=()=>{this.send({type:'hello',protocol:'TK-EDGE-1',checkpoint:this.initial});this.onStatus('Channel open; checking initial checkpoint.');};c.onclose=()=>{this.ready=false;this.onStatus('Peer disconnected. Pending rounds remain deferred.');};c.onmessage=e=>{this.incoming=(this.incoming??Promise.resolve()).then(()=>this.message(e.data)).catch(err=>{this.ready=false;this.rounds.failed=err.message;this.send({type:'error',message:err.message});this.onStatus('Session halted: '+err.message);});};}
 async message(raw){need(typeof raw==='string'&&raw.length<=1000000,'Message budget exceeded');const p=JSON.parse(raw);if(p.type==='hello'){need(p.protocol==='TK-EDGE-1'&&canonical(p.checkpoint)===canonical(this.initial),'Initial checkpoint differs');this.ready=true;this.onStatus('Peer ready · identical initial checkpoint');return;}need(this.ready,'Peer is not initialized');if(p.type==='hop'){need(p.event.member!==this.member,'Peer used local member identity');await this.rounds.receive(p.event);if(this.passive&&p.event.round>=this.rounds.round&&!this.rounds.pending.get(p.event.round)?.has(this.member))await this.stage({kind:'idle'},p.event.round);}else if(p.type==='commit'){need(Number.isInteger(p.round)&&p.round>=0&&p.round<4096&&this.receipts.size<64,'Receipt budget exceeded');this.receipts.set(p.round,p.checkpoint);this.checkReceipts();}else if(p.type==='error')throw Error('Peer halted: '+p.message);else throw Error('Unknown peer message');}
 async stage(event,round=this.rounds.round){need(this.ready,'Peer initialization is incomplete');need(!this.rounds.pending.get(round)?.has(this.member),'This member already filled the round');const p={...event,round,member:this.member};this.send({type:'hop',event:p});const result=await this.rounds.receive(p);if(!result.length)this.onStatus('DEFER · waiting for the other member slot');return result;}
 createPC(iceServers){this.pc=new RTCPeerConnection({iceServers});this.pc.onconnectionstatechange=()=>this.onStatus('Connection: '+this.pc.connectionState);this.pc.ondatachannel=e=>this.attach(e.channel);}
 async gather(){if(this.pc.iceGatheringState==='complete')return;await new Promise((resolve,reject)=>{const pc=this.pc,t=setTimeout(()=>{pc.removeEventListener('icegatheringstatechange',f);reject(Error('ICE gathering timed out; retry or change ICE servers'));},20000),f=()=>{if(pc.iceGatheringState==='complete'){clearTimeout(t);pc.removeEventListener('icegatheringstatechange',f);resolve();}};pc.addEventListener('icegatheringstatechange',f);});}
 async offer(iceServers=[]){this.reset(this.machine.checkpoint(),'A');this.createPC(iceServers);this.attach(this.pc.createDataChannel('tk-edge-1',{ordered:true}));await this.pc.setLocalDescription(await this.pc.createOffer());await this.gather();return{type:'offer',protocol:'TK-EDGE-1',sdp:this.pc.localDescription.sdp,checkpoint:this.initial,iceServers};}
 async answer(offer){need(offer.type==='offer'&&offer.protocol==='TK-EDGE-1','Invalid offer');this.reset(offer.checkpoint,'B');this.createPC(offer.iceServers??[]);await this.pc.setRemoteDescription({type:'offer',sdp:offer.sdp});await this.pc.setLocalDescription(await this.pc.createAnswer());await this.gather();return{type:'answer',protocol:'TK-EDGE-1',sdp:this.pc.localDescription.sdp};}
 async accept(answer){need(answer.type==='answer'&&answer.protocol==='TK-EDGE-1'&&this.member==='A'&&this.pc,'Invalid answer');await this.pc.setRemoteDescription({type:'answer',sdp:answer.sdp});}
 replay(){return{protocol:'TK-EDGE-1',initial:this.initial,members:this.rounds.members,events:this.log};}
}
